// Avisa al jefe de cada área (con copia a RRHH) cuando a un contrato o certificación le faltan exactamente 15 o 5 días.
// Corre una vez al día: si un día no corre, ese aviso se pierde (la app sigue mostrando el semáforo).
const AVISOS = [15, 5];
const pad = n => String(n).padStart(2, '0');
const ahora = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Bogota' }));
const hoy = `${ahora.getFullYear()}-${pad(ahora.getMonth() + 1)}-${pad(ahora.getDate())}`;
const dias = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / 864e5);
const fmt = s => s.split('-').reverse().join('/');
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const docs = n => $(n).all().map(i => i.json).filter(d => d && Object.keys(d).length);

const cfg = docs('Config').find(c => (c._id || c.id) === 'general') || {};
const emps = new Map(docs('Empleados').filter(e => e.estado !== 'retirado').map(e => [String(e.cedula || e._id), e]));
// Jefe de cada área = colaborador activo elegido en Ajustes (areas[].jefeCedula).
const jefes = new Map((cfg.areas || []).map(a => [a.nombre, emps.get(String(a.jefeCedula))]).filter(([, j]) => j));

const ctr = new Map();
for (const c of docs('Contratos')) if (!ctr.has(c.cedula) || ctr.get(c.cedula).inicio < c.inicio) ctr.set(c.cedula, c);
const cert = new Map();
for (const c of docs('Certificaciones')) {
  if (!c.vencimiento) continue;
  const k = c.cedula + '|' + c.tipo;
  if (!cert.has(k) || cert.get(k).vencimiento < c.vencimiento) cert.set(k, c);
}

const filas = [];
for (const c of ctr.values()) if (c.fin) filas.push({ ced: c.cedula, que: `Contrato ${c.tipo}`, fecha: c.fin });
for (const c of cert.values()) filas.push({ ced: c.cedula, que: c.tipo, fecha: c.vencimiento });

const porCorreo = {};
for (const f of filas) {
  const e = emps.get(String(f.ced));
  const d = dias(hoy, f.fecha);
  if (!e || !AVISOS.includes(d)) continue;
  const j = jefes.get(e.area);
  const correoJefe = j && (j.correoEmpresarial || j.correoPersonal);
  const para = correoJefe || cfg.correoRRHH; // sin jefe activo o sin correo: va a RRHH
  if (!para) continue;
  (porCorreo[para] ||= { jefe: correoJefe ? j.nombres : 'equipo de Talento Humano', filas: [] }).filas.push({ ...f, d, e });
}

return Object.entries(porCorreo).map(([to, g]) => ({
  json: {
    to,
    cc: cfg.correoRRHH && cfg.correoRRHH !== to ? cfg.correoRRHH : '',
    subject: `Vencimientos próximos: ${g.filas.length} colaborador(es)`,
    html: `<p>Hola ${esc(g.jefe)},</p><p>Estos vencimientos de tu equipo requieren gestión:</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:Arial;font-size:13px">
<tr style="background:#0f2a4a;color:#fff"><th>Colaborador</th><th>Cédula</th><th>Cargo</th><th>Qué vence</th><th>Fecha</th><th>Días</th></tr>
${g.filas.sort((a, b) => a.d - b.d).map(f => `<tr><td>${esc(f.e.nombres)} ${esc(f.e.apellidos)}</td><td>${esc(f.ced)}</td><td>${esc(f.e.cargo)}</td><td>${esc(f.que)}</td><td>${fmt(f.fecha)}</td><td><b>${f.d}</b></td></tr>`).join('\n')}
</table><p>Por favor confirma a Talento Humano si se renueva o no.</p>`,
  },
}));
